example.code:
[HttpGet("{id}")]
[ProducesUnionResponseType(typeof(User), StatusCodes.Status200OK)]
[ProducesUnionResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound)]
[ProducesUnionResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]
public Result<User, ProblemDetailsError> GetUser(int id)
{
    return _userService.GetUser(id);
}

[GenerateUnion]
public partial class Result<T, E>
{
    [UnionStatusCode(201)] // Created
    public static Result<T, E> Created(T value) => new CreatedCase(value);

    [UnionStatusCode(404)] // Not Found
    public static Result<T, E> NotFound(E error) => new NotFoundCase(error);

    [UnionStatusCode(409)] // Conflict
    public static Result<T, E> Conflict(E error) => new ConflictCase(error);
}

[UnionStatusCode(404)]
public class NotFoundError { }

[UnionStatusCode(409)]
public class ConflictError { }

remarks.para:
            Supported property signatures:


int StatusCode { get; }

int Status { get; }

int HttpStatusCode { get; }

example.code:
public class CustomError
{
    public int StatusCode => 418; // I'm a teapot
}

public class DomainError
{
    public int Status { get; init; } = 422;
}

var registry = StatusCodeConventionRegistry.Default;

if (registry.TryInferStatusCode(error, out int statusCode))
{
    return StatusCode(statusCode, error);
}
else
{
    return StatusCode(500, error); // Fallback
}

[HttpPost]
public IActionResult CreateUser(CreateUserDto dto)
{
    if (!ModelState.IsValid)
    {
        var error = ModelState.ToProblemDetailsError(HttpContext.Request.Path);
        return Result<User, ProblemDetailsError>.Error(error).ToActionResult();
    }

    // ... process valid model
}

if (!ModelState.IsValid)
{
    var error = ModelState.ToProblemDetailsError(
        HttpContext.Request.Path,
        "The user creation request contains invalid data. Please verify all required fields."
    );
    return error.ToActionResult();
}

[HttpPost]
public IActionResult CreateUser(CreateUserDto dto)
{
    if (ModelState.TryGetValidationError(HttpContext.Request.Path, out var error))
    {
        return Result<User, ProblemDetailsError>.Error(error).ToActionResult();
    }

    // ... process valid model
}

// In a controller action
[HttpGet("{id}")]
public IActionResult GetUser(int id)
{
    Result<User, ProblemDetailsError> result = userService.GetUser(id);
    return result.ToActionResult();
}

// With custom success status
[HttpPost]
public IActionResult CreateUser(CreateUserDto dto)
{
    Result<User, ProblemDetailsError> result = userService.CreateUser(dto);
    return result.ToActionResult(successStatusCode: 201);
}

// With custom error type
Result<User, DomainError> result = userService.GetUser(id);

return result.ToActionResult(
    errorMapper: domainError => ProblemDetailsErrorFactory.BadRequest(
        HttpContext.Request.Path,
        domainError.Message
    )
);

var error = ProblemDetailsErrorFactory.NotFound(
    HttpContext.Request.Path,
    "User not found."
);
return error.ToActionResult();

services.AddUnionResultHandling();

// Or with custom configuration
services.AddUnionResultHandling(options =>
{
    options.LoggingOptions.LogErrorDetails = true;
    options.LoggingOptions.LogConventionInference = true;
});

services.AddUnionResultHandling(sp =>
{
    var registry = new StatusCodeConventionRegistry();
    registry.Register(new MyCustomConvention());
    return registry;
});

// Apply globally to all endpoints
var app = builder.Build();
app.MapGet("/api/users/{id}", GetUser)
   .AddEndpointFilter<UnionEndpointFilter>();

Result<User, ProblemDetailsError> GetUser(int id)
{
    return userService.GetUser(id);
}

// Or create an extension method for convenience
public static class RouteHandlerBuilderExtensions
{
    public static RouteHandlerBuilder WithUnionSupport(this RouteHandlerBuilder builder)
    {
        return builder.AddEndpointFilter<UnionEndpointFilter>();
    }
}

app.MapGet("/api/users/{id}", GetUser).WithUnionSupport();

// Apply globally in Program.cs / Startup.cs
builder.Services.AddControllers(options =>
{
    options.Filters.Add<UnionResultFilter>();
});

// Or apply per-controller
[ServiceFilter(typeof(UnionResultFilter))]
public class UsersController : ControllerBase
{
    [HttpGet("{id}")]
    public Result<User, ProblemDetailsError> GetUser(int id)
    {
        // Return union directly - filter handles conversion
        return _userService.GetUser(id);
    }
}

